operation.add:
	if ((int)$this->config->get('module_sitewidget_sms_registration_enabled') === 1) {
	$this->load->model('extension/sitewidget/sms_delivery');
	$verification_token = (string)($post_info['sitewidget_phone_verification'] ?? '');

	if (!$this->model_extension_sitewidget_sms_delivery->validateGrant((string)$post_info['telephone'], $verification_token)) {
		$json['error']['telephone'] = 'Подтвердите номер телефона кодом из SMS.';
		$this->response->addHeader('Content-Type: application/json');
		$this->response->setOutput(json_encode($json));
		return;
	}
}

	$customer_id = $this->model_account_customer->addCustomer($post_info);

	if ((int)$this->config->get('module_sitewidget_sms_registration_enabled') === 1) {
		$this->model_extension_sitewidget_sms_delivery->consumeGrant((string)($post_info['sitewidget_phone_verification'] ?? ''));
	}
